import { autoPick, init as initSnake, pick as snakePick, validatePick, turnPlayer } from "../engine";
import { next, shuffle } from "../rng";
import type { Config, Item, State } from "../types";

export type SpinState = {
  draft: State;
  offer: string[];
  rerolls: Record<string, number>;
  options: number;
  seed: number;
};

function makeOffer(draft: State, options: number, seed: number, hasRoles: boolean): [string[], number] {
  const picked = new Set(draft.picks.map((p) => p.itemId));
  const candidates = draft.pool
    .filter((i) => !picked.has(i.id) && !draft.banned.includes(i.id))
    .filter((i) => hasRoles || validatePick(draft, i.id).ok)
    .map((i) => i.id);
  const [shuffled, s] = shuffle(candidates, seed);
  return [shuffled.slice(0, options), s];
}

export function init(config: Config, pool: Item[], options: number, rerolls: number, seed: number): SpinState {
  const draft = initSnake(config, pool);
  const [offer, s] = makeOffer(draft, options, seed, config.roles.length > 0);
  return { draft, offer, rerolls: Object.fromEntries(config.players.map((p) => [p, rerolls])), options, seed: s };
}

export function pick(s: SpinState, itemId: string, role?: string): SpinState {
  if (!s.offer.includes(itemId) || !validatePick(s.draft, itemId, role).ok) return s;
  const draft = snakePick(s.draft, itemId, role);
  const [offer, seed] = draft.done ? [[], s.seed] : makeOffer(draft, s.options, s.seed, draft.config.roles.length > 0);
  return { ...s, draft, offer, seed };
}

/** Reroll costs a token and refreshes the offer; the options come back into the pool. */
export function reroll(s: SpinState): SpinState {
  if (s.draft.done) return s;
  const p = turnPlayer(s.draft);
  if (s.rerolls[p]! <= 0) return s;
  const [offer, seed] = makeOffer(s.draft, s.options, s.seed, s.draft.config.roles.length > 0);
  return { ...s, offer, seed, rerolls: { ...s.rerolls, [p]: s.rerolls[p]! - 1 } };
}

/** Best of the current offer (AI / timeout). */
export function auto(s: SpinState, weights?: Record<string, number>): SpinState {
  if (s.draft.done) return s;
  const only: State = { ...s.draft, pool: s.draft.pool.filter((i) => s.offer.includes(i.id)) };
  const after = autoPick(only, weights);
  const last = after.picks[after.picks.length - 1];
  if (!last || after.picks.length === s.draft.picks.length) return s;
  return pick(s, last.itemId, last.role);
}

